async (page) => {
  const fs = require('fs');
  const path = require('path');
  const root = '/tmp/mcp-workspace';
  const cutoff = Date.now() - 24 * 60 * 60 * 1000;
  const results = [];
  function walk(dir) {
    const entries = fs.readdirSync(dir, { withFileTypes: true });
    for (const e of entries) {
      const full = path.join(dir, e.name);
      try {
        if (e.isDirectory()) {
          walk(full);
        } else if (e.isFile()) {
          const st = fs.statSync(full);
          if (st.mtimeMs >= cutoff) {
            results.push({ path: full, mtime: st.mtime.toISOString() });
          }
        }
      } catch (err) {}
    }
  }
  walk(root);
  return results;
}

